<?php
require_once __DIR__.'/includes/db.php';require_login();
$cart=$_SESSION['cart']??[];$error='';$items=[];$total=0;
if($cart){$ids=array_map('intval',array_keys($cart));$marks=implode(',',array_fill(0,count($ids),'?'));$st=$pdo->prepare("SELECT id,name,price FROM products WHERE id IN ($marks) AND active=1");$st->execute($ids);$items=$st->fetchAll();foreach($items as $it)$total+=(float)$it['price']*(int)$cart[$it['id']];}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$address=trim($_POST['address']??'');if(!$items)$error='Your cart is empty.';elseif(strlen($address)<10)$error='Please enter a complete delivery address.';else{
 $pdo->beginTransaction();try{$orderNo='GC'.date('ymd').strtoupper(bin2hex(random_bytes(3)));$st=$pdo->prepare("INSERT INTO orders(user_id,order_no,total,address,status,payment_status) VALUES(?,?,?,?, 'Pending','Unpaid')");$st->execute([$_SESSION['user_id'],$orderNo,$total,$address]);$orderId=(int)$pdo->lastInsertId();$line=$pdo->prepare("INSERT INTO order_items(order_id,product_id,product_name,price,quantity) VALUES(?,?,?,?,?)");foreach($items as $it)$line->execute([$orderId,$it['id'],$it['name'],$it['price'],$cart[$it['id']]]);$pdo->commit();$_SESSION['cart']=[];header('Location: track.php?order='.urlencode($orderNo));exit;}catch(Throwable $e){$pdo->rollBack();$error='Could not create the order. Please try again.';}
}}
